def check_bibd(matrix_flat, v, b, r, k, lam):
    matrix = [matrix_flat[i*b:(i+1)*b] for i in range(v)]

    # Check row sums
    for i in range(v):
        if sum(matrix[i]) != r:
            return False, f"Row {i} sum is {sum(matrix[i])}, expected {r}"

    # Check column sums
    for j in range(b):
        col_sum = sum(matrix[i][j] for i in range(v))
        if col_sum != k:
            return False, f"Column {j} sum is {col_sum}, expected {k}"

    # Check inner products
    for i1 in range(v):
        for i2 in range(i1 + 1, v):
            inner_prod = sum(matrix[i1][j] * matrix[i2][j] for j in range(b))
            if inner_prod != lam:
                return False, f"Inner product of row {i1} and {i2} is {inner_prod}, expected {lam}"

    return True, "OK"

